import { View, Text, Pressable, StyleSheet } from "react-native";
import { useState } from "react";
import { registerRootComponent } from "expo";

function App() {
  const [cart, setCart] = useState(0);
  return (
    <View style={styles.container}>
      <Pressable nativeID="add" style={styles.add} onPress={() => setCart((c) => c + 1)}>
        <Text style={styles.addText}>Сагслах</Text>
      </Pressable>
      <View style={styles.tabbar}>
        <View style={styles.tab}><Text style={styles.tabText}>Нүүр</Text></View>
        <View style={styles.tab}>
          <Text style={styles.tabText}>Сагс</Text>
          {/* энд бичнэ үү: cart > 0 бол badge (nativeID "badge") харуул */}
        </View>
        <View style={styles.tab}><Text style={styles.tabText}>Профайл</Text></View>
      </View>
    </View>
  );
}

const styles = StyleSheet.create({
  container: { flex: 1, justifyContent: "flex-end" },
  add: { margin: 24, backgroundColor: "#2563eb", padding: 14, borderRadius: 12, alignItems: "center" },
  addText: { color: "#fff", fontWeight: "bold" },
  tabbar: { flexDirection: "row", borderTopWidth: 1, borderTopColor: "#e5e7eb" },
  tab: { flexGrow: 1, paddingVertical: 12, alignItems: "center" },
  tabText: { fontWeight: "600", color: "#334155" },
  badge: { position: "absolute", top: 2, right: 24, backgroundColor: "#dc2626", color: "#fff", fontSize: 12, fontWeight: "bold", minWidth: 18, textAlign: "center", paddingHorizontal: 5, borderRadius: 999 },
});

registerRootComponent(App);

import { View, Text, Pressable, StyleSheet } from "react-native";
import { useState } from "react";
import { registerRootComponent } from "expo";

function App() {
  const [cart, setCart] = useState(0);
  return (
    <View style={styles.container}>
      <Pressable nativeID="add" style={styles.add} onPress={() => setCart((c) => c + 1)}>
