          <Text style={styles.tabText}>Сагс</Text>
          {cart > 0 && <Text nativeID="badge" style={styles.badge}>{cart}</Text>}
        </View>
        <View style={styles.tab}><Text style={styles.tabText}>Профайл</Text></View>
      </View>
    </View>
  );
}

